function collect(){const p=people[0],s=mission.steps[mission.cursor];s.output=outputFor(s);if(s.agent===0){s.status='Completada';mission.cursor++;dispatch();return}const w=people[s.agent];setMode(w,'handoff');mission.status='Nico recoge el trabajo de '+w.name;route(p,[w.home[0]-Math.sign(w.home[0])*1.05,w.home[1]],()=>{p.yaw=Math.sign(w.home[0])*Math.PI/2;setMode(p,'handoff',2);announce(w.name+' comparte sus resultados con Nico.')})}
