function tickPaul(dt){director.phase+=dt*8;if(director.mode!=='walking')return;const q=director.route[0];if(!q)return;const dx=q[0]-director.pos[0],dz=q[1]-director.pos[1],d=Math.hypot(dx,dz),step=dt*2;director.yaw=Math.atan2(dx,dz);if(d<=step){director.pos=[...q];director.route.shift();if(!director.route.length){const atDesk=Math.hypot(director.pos[0]+5.6,director.pos[1]-17.1)<.1;director.mode=atDesk?'idle':'standing';if(atDesk)director.yaw=Math.PI}}else{director.pos[0]+=dx/d*step;director.pos[1]+=dz/d*step}}
