$('follow').onchange=()=>{const view=$('follow').value;const zones={cafe:[5.6,.65,-12.2],lounge:[-5.6,.65,-12.2],bathroom:[0,.65,-17.35]};if(zones[view]){follow='general';target=zones[view];distance=view==='bathroom'?11:15}else{follow=view;distance=follow==='general'?43:12;if(follow==='general')target=[0,.5,0]}};
